package org.apache.commons.compress.archivers.tar;

import java.io.*;
import java.io.ByteArrayOutputStream;
import java.io.File;
import java.io.IOException;
import java.io.OutputStream;
import java.math.*;
import java.util.*;
import org.apache.commons.compress.archivers.ArchiveEntry;
import org.apache.commons.compress.archivers.ArchiveOutputStream;
import org.apache.commons.compress.archivers.tar.TarArchiveEntry;
import org.junit.*;
import org.junit.Assert;
import org.junit.Test;
import static org.junit.Assert.*;

public class TarArchiveOutputStream_finish_TriageGen0Test {

    @Test
    public void testFinishWritesTwoEOFRecords() throws IOException {
        ByteArrayOutputStream baos = new ByteArrayOutputStream();
        try (TarArchiveOutputStream taos = new TarArchiveOutputStream(baos)) {
            // Add a dummy entry to ensure the stream is in a valid state for finishing
            TarArchiveEntry entry = new TarArchiveEntry("test.txt");
            taos.putArchiveEntry(entry);
            taos.write("test".getBytes());
            taos.closeArchiveEntry();

            taos.finish();
        }

        byte[] result = baos.toByteArray();

        // In TAR format, an EOF record is a block of 512 zero bytes.
        // The finish() method calls writeEOFRecord() twice.
        // We check if the end of the stream contains two blocks of 512 zero bytes.

        int expectedEofBlockSize = 512;
        int expectedTotalEofBytes = expectedEofBlockSize * 2;

        Assert.assertTrue("Resulting array should be at least large enough for two EOF blocks", 
                result.length >= expectedTotalEofBytes);

        // Check the last 512 bytes
        for (int i = result.length - expectedEofBlockSize; i < result.length; i++) {
            Assert.assertEquals("Last EOF block byte should be 0", 0, result[i]);
        }

        // Check the 512 bytes before the last 512 bytes
        for (int i = result.length - (expectedEofBlockSize * 2); i < result.length - expectedEofBlockSize; i++) {
            Assert.assertEquals("Second to last EOF block byte should be 0", 0, result[i]);
        }
    }

    @Test
    public void testFinishWithNoEntries() throws IOException {
        ByteArrayOutputStream baos = new ByteArrayOutputStream();
        try (TarArchiveOutputStream taos = new TarArchiveOutputStream(baos)) {
            taos.finish();
        }

        byte[] result = baos.toByteArray();

        // Even with no entries, finish() should write two EOF records (1024 bytes)
        Assert.assertEquals("Should contain exactly two EOF blocks when no entries added", 
                1024, result.length);

        for (byte b : result) {
            Assert.assertEquals(0, b);
        }
    }

    @Test(expected = IOException.class)
    public void testFinishThrowsExceptionWhenOutputStreamIsClosed() throws IOException {
        ByteArrayOutputStream baos = new ByteArrayOutputStream();
        TarArchiveOutputStream taos = new TarArchiveOutputStream(baos);
        baos.close(); // Close the underlying stream

        // This should trigger an IOException when writeEOFRecord attempts to write
        taos.finish();
    }
}
